/**
 * Character asset manifest: public/assets/characters.json.
 *
 * Generated by `pnpm --filter @paradox/web characters:manifest`
 * (scripts/build-character-manifest.mjs), which scans
 *   public/assets/raw/characters/*.fbx|glb   (Mixamo characters, T-pose, with skin)
 *   public/assets/raw/animations/*.fbx|glb   (Mixamo animations, without skin, in place)
 * and maps file names ("Rifle Idle.fbx", "Strafe Left.fbx", ...) to the clip ids below.
 */

export type ClipId =
  | "idle"
  | "walk_fwd"
  | "walk_back"
  | "strafe_l"
  | "strafe_r"
  | "run"
  | "sprint"
  | "crouch_idle"
  | "crouch_walk"
  | "jump"
  | "fall"
  | "land"
  | "reload"
  | "fire"
  | "hit"
  | "death"
  | "victory"
  | "emote";

export interface CharacterEntry {
  /** Stable id derived from the file name, e.g. "swat-guy". */
  id: string;
  /** Display name, e.g. "Swat Guy". */
  name: string;
  url: string;
}

export interface CharacterManifest {
  characters: CharacterEntry[];
  /** Clip id → one or more files (several deaths / emotes are allowed). */
  clips: Partial<Record<ClipId, string[]>>;
}

export const MANIFEST_URL = "/assets/characters.json";

let manifestPromise: Promise<CharacterManifest> | null = null;

export function loadManifest(): Promise<CharacterManifest> {
  manifestPromise ??= fetch(MANIFEST_URL).then((r) => {
    if (!r.ok) throw new Error(`Character manifest missing (${r.status}). Run the characters:manifest script.`);
    return r.json() as Promise<CharacterManifest>;
  });
  return manifestPromise;
}
